const inp = $input.first().json;
const body = inp.body || inp;
const image = body.image_url || body.image1_url;
if (!image) throw new Error('image_url is required');

let length = parseInt(body.length_seconds, 10);
if (!Number.isInteger(length) || length < 4 || length > 24) length = 12;
let ratio = String(body.ratio || '9:16').toLowerCase();
if (ratio === 'smart') ratio = 'adaptive';
let resolution = String(body.resolution || '720p').toLowerCase();

// Scene count from length: <8s -> 1, 8-12s -> 2, >12s -> 3. Each clip >= 4s
// (Seedance minimum), capped at 6. Durations always sum to the reel length.
const byLength = length < 8 ? 1 : length <= 12 ? 2 : 3;
const maxByMin = Math.max(1, Math.floor(length / 4));
const numClips = Math.min(Math.max(byLength, 1), maxByMin, 6);
const base = Math.floor(length / numClips);
let rem = length - base * numClips;
const durations = Array.from({ length: numClips }, () => base);
for (let i = 0; i < rem; i++) durations[i] += 1;

return [{ json: { image_url: image, length_seconds: length, ratio, resolution, num_clips: numClips, durations } }];

const setup = $('Storyboard Setup').first().json;
const binary = $input.first().binary || {};
const key = binary.data ? 'data' : Object.keys(binary)[0];
if (!key) throw new Error('No image binary fetched for the storyboard');
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const b64 = buf.toString('base64');
const mimeType = (binary[key] && binary[key].mimeType) || 'image/jpeg';

const N = setup.num_clips;

const lines = [
  'You are a world-class creative director for luxury jewellery reels on Instagram. The attached photo shows ONE jewellery item, and it may or may not be worn by a model.',
  '',
  'STEP 1 - Look at the photo carefully and note: what the piece is (ring, necklace, earrings, bangle, etc.), its metal colour and its stones; AND whether the photo shows a MODEL wearing the piece, or the PRODUCT on its own.',
  '',
  'STEP 2 - Design EXACTLY ' + N + ' DIFFERENT, eye-catching scenes for a premium reel. Each scene must be a DISTINCT creative idea. Do NOT make every scene a zoom-in on the jewellery. Pick varied shots that fit the photo.',
  'IMPORTANT: if the photo shows a MODEL wearing the jewellery, then the SAME model must appear in EVERY scene wearing the SAME piece - do NOT switch to product-only shots. Use model-based ideas like: she slowly turns her head or hand so the piece catches the light; her hand rises gracefully to touch or frame the necklace/earring; she walks forward in slow motion as the jewellery shines; a soft smile and glance to camera as the stones sparkle; wind gently moving her hair or dupatta while the piece stays in focus; a slow move from a wide shot of her to a close look at the jewellery she is wearing.',
  'ONLY if the photo is the PRODUCT on its own (no person), use product ideas like: the ring or piece drops into water in slow motion with a gentle splash and ripples; the piece rests on flowing silk or velvet that ripples softly; warm golden light rays and sparkles sweep across the stones; soft petals, water droplets or tiny light particles drift around it; the piece turns slowly on a clean pedestal under a moving spotlight; a hand gently places the piece down on a marble surface.',
  '',
  'STEP 3 - For each scene, write in SIMPLE, PLAIN ENGLISH. Use short, clear sentences and everyday words - no fancy or poetic language. Provide:',
  '- "title": 2 to 4 simple words.',
  '- "prompt": describe what happens in the shot in plain English - the main action or effect, a smooth slow camera move, the lighting and mood, and the background. Keep the jewellery design exactly as in the photo, but you ARE allowed to add creative backgrounds and effects (water, a splash, silk, petals, sparkles, light rays). Keep the piece clearly in frame.',
  '- "caption": a short on-screen line a jeweller could show (max 6 words), or an empty string.',
  '',
  'Make the ' + N + ' scenes feel varied, fresh and cinematic together, like a high-end advert a jeweller would be proud to post. Return STRICT JSON ONLY (no markdown, no code fences): {"analysis":"one simple line about the piece","style_name":"a short simple name for the overall look","scenes":[{"title":"","prompt":"","caption":""}]}',
  'The scenes array MUST contain exactly ' + N + ' item(s).'
];
const instruction = lines.join('\n');

const geminiBody = {
  contents: [{ role: 'user', parts: [ { text: instruction }, { inlineData: { mimeType, data: b64 } } ] }],
  generationConfig: { responseMimeType: 'application/json', temperature: 1.15 }
};

return [{ json: { ...setup, geminiBody }, binary: $input.first().binary }];

const setup = $('Storyboard Setup').first().json;
const durations = setup.durations || [];
const N = setup.num_clips;
const resp = $input.first().json;

// Pull the model's text out of the Vertex generateContent response.
let text = null;
try {
  const cands = resp.candidates || (resp.data && resp.data.candidates) || [];
  for (const c of cands) {
    const parts = (c.content && c.content.parts) || [];
    for (const p of parts) { if (typeof p.text === 'string' && p.text.trim()) { text = p.text; break; } }
    if (text) break;
  }
} catch (e) {}

// Parse the JSON object out of the text (tolerant of any stray wrapping).
let parsed = null;
if (text) {
  const a = text.indexOf('{');
  const b = text.lastIndexOf('}');
  if (a !== -1 && b !== -1 && b > a) {
    try { parsed = JSON.parse(text.slice(a, b + 1)); } catch (e) { parsed = null; }
  }
}

// Fallback storyboard (photo-agnostic) so the user always gets an editable script.
const FALLBACK = {
  style_name: 'Luxury Mix',
  analysis: 'Your jewellery piece',
  scenes: [
    { title: 'Silk Reveal', prompt: 'The jewellery rests on soft flowing silk that ripples gently in a light breeze. Warm light glows behind it. The camera slowly pushes in as the stones start to sparkle.', caption: '' },
    { title: 'Water Splash', prompt: 'The piece is shown in slow motion as a few water droplets fall and splash near it, sending out soft ripples and tiny sparkles. Clean bright light. The camera holds steady and close.', caption: '' },
    { title: 'Golden Glow', prompt: 'Warm golden light rays sweep across the jewellery and small sparkles drift in the air. The camera slowly pulls back to a soft, glowing hero shot.', caption: '' }
  ]
};

const sceneSrc = (parsed && Array.isArray(parsed.scenes) && parsed.scenes.length) ? parsed.scenes : FALLBACK.scenes;

const scenes = [];
for (let i = 0; i < N; i++) {
  const s = sceneSrc[i] || sceneSrc[sceneSrc.length - 1] || FALLBACK.scenes[Math.min(i, FALLBACK.scenes.length - 1)];
  const fb = FALLBACK.scenes[Math.min(i, FALLBACK.scenes.length - 1)];
  scenes.push({
    order: i,
    title: String(s.title || ('Scene ' + (i + 1))).slice(0, 60),
    duration: durations[i] || Math.max(4, Math.floor(setup.length_seconds / N)),
    prompt: String(s.prompt || fb.prompt).slice(0, 600),
    caption: String(s.caption || '').slice(0, 60)
  });
}

return [{ json: {
  ok: true,
  analysis: String((parsed && parsed.analysis) || FALLBACK.analysis).slice(0, 200),
  style_name: String((parsed && parsed.style_name) || FALLBACK.style_name).slice(0, 80),
  length_seconds: setup.length_seconds,
  ratio: setup.ratio,
  resolution: setup.resolution,
  num_scenes: N,
  scenes
}}];

const inp = $input.first().json;
const body = inp.body || inp;

const allowedRatios = ['9:16','16:9','1:1','4:3','3:4','21:9','adaptive'];
const allowedRes = ['480p','720p','1080p'];
const ALLOW_1080 = true;

const userId = body.user_id;
// Storyboard mode: ONE photo drives every scene/clip.
const image = body.image_url || body.image1_url;
if (!userId) throw new Error('user_id is required');
if (!image) throw new Error('image_url is required');

let length = parseInt(body.length_seconds, 10);
let ratio = String(body.ratio || '9:16').toLowerCase();
if (ratio === 'smart') ratio = 'adaptive';
let resolution = String(body.resolution || '720p').toLowerCase();
const customPrompt = String(body.custom_prompt || '').trim();
const musicId = body.music_id || null;
const musicUrl = (typeof body.music_url === 'string' && body.music_url.trim()) ? body.music_url.trim() : null;

const overlayText = String(body.overlay_text || '').trim().slice(0, 80) || null;
const overlayPosition = overlayText ? (body.overlay_position === 'end' ? 'end' : 'whole') : null;
const FONT_KEYS = ['sans','serif','mono'];
const COLOR_KEYS = ['white','black','gold','navy','red','cream'];
const overlayFont = overlayText ? (FONT_KEYS.includes(String(body.overlay_font || '').toLowerCase()) ? String(body.overlay_font).toLowerCase() : 'sans') : null;
const overlayColor = overlayText ? (COLOR_KEYS.includes(String(body.overlay_color || '').toLowerCase()) ? String(body.overlay_color).toLowerCase() : 'white') : null;

if (!allowedRatios.includes(ratio)) throw new Error('invalid ratio: ' + ratio);
if (!allowedRes.includes(resolution)) throw new Error('invalid resolution: ' + resolution);
if (!Number.isInteger(length) || length < 4 || length > 24) throw new Error('length_seconds must be an integer between 4 and 24');

let resolutionUsed = resolution;
if (resolution === '1080p' && !ALLOW_1080) resolutionUsed = '720p';

// Edited storyboard from the app. Each scene supplies its own prompt (and,
// optionally, a duration). Keep only scenes with a real prompt.
let scenes = Array.isArray(body.scenes)
  ? body.scenes.filter((s) => s && typeof s.prompt === 'string' && s.prompt.trim())
  : [];
if (!scenes.length) throw new Error('scenes[] is required - run the storyboard step first');
const maxByMin = Math.max(1, Math.floor(length / 4));
const cap = Math.min(6, maxByMin);
if (scenes.length > cap) scenes = scenes.slice(0, cap);
const numClips = scenes.length;

// Use the per-scene durations if they are valid and sum to the reel length;
// otherwise split the length evenly (each clip >= 4s, remainder on the front).
let durations = scenes.map((s) => parseInt(s.duration, 10)).filter((n) => Number.isInteger(n) && n >= 4);
const sumOk = durations.length === numClips && durations.reduce((a, b) => a + b, 0) === length;
if (!sumOk) {
  const base = Math.floor(length / numClips);
  let rem = length - base * numClips;
  durations = Array.from({ length: numClips }, () => base);
  for (let i = 0; i < rem; i++) durations[i] += 1;
}

// Guards appended to EVERY prompt server-side. They lock the PIECE's design and
// keep the camera cinematic, but deliberately ALLOW creative backgrounds and
// effects (water, silk, petals, light) so scenes don't all become the same zoom.
const PACING = 'Use smooth, cinematic slow-motion. The camera moves slowly and steadily - a gentle push-in, a soft arc, or a slow reveal - with no spinning and no full 360 rotation. Dynamic effects such as a water splash, rippling silk, drifting petals or floating light particles are welcome, but the jewellery always stays clearly in frame and in sharp focus.';
const FIDELITY = 'Keep the jewellery piece itself exactly as in the reference image - the same design, stones, metal colour, shape and proportions. Creative backgrounds, lighting and effects are encouraged. If a person is shown, keep her face and identity unchanged. No on-screen text, no logos, no watermarks.';

const endDur = Math.min(4, Math.max(1, Math.ceil(length / 2)));
const overlayStartAt = overlayPosition === 'end' ? length - endDur : 0;

// Credits are charged ONLY when the reel completes (trg_reel_charge_on_complete).
// Compute the cost server-side (never trust the client): the video render cost
// (ceil(seconds x rate), min 1) plus +1 per scene for the AI first-frame. Rates
// MUST match src/lib/plans.js REEL_UNITS_PER_SECOND.
const REEL_RATE = { '480p': 0.35, '720p': 0.75, '1080p': 1.6 };
const rate = REEL_RATE[resolution] || REEL_RATE['720p'];
const videoCost = Math.max(1, Math.ceil(length * rate));
const creditsCost = videoCost + numClips;

const clips = scenes.map((s, i) => {
  const scene = String(s.prompt).trim();
  // scene_prompt drives the per-scene first-frame image; prompt (with the guards)
  // drives the Seedance motion. Both come from the same edited scene text.
  let scenePrompt = scene;
  if (customPrompt) scenePrompt += '. ' + customPrompt;
  const motionPrompt = scenePrompt + '. ' + PACING + ' ' + FIDELITY;
  return { order: i, duration: durations[i], first_frame_url: image, prompt: motionPrompt, scene_prompt: scenePrompt };
});

return [{ json: {
  user_id: userId,
  length_seconds: length, num_clips: numClips,
  ratio, resolution, resolution_used: resolutionUsed,
  input_images: [image], custom_prompt: customPrompt || null, music_id: musicId, music_url: musicUrl,
  overlay_text: overlayText, overlay_position: overlayPosition, overlay_start_at: overlayStartAt,
  overlay_font: overlayFont, overlay_color: overlayColor,
  credits_cost: creditsCost,
  style_pack: 'storyboard', style_name: String(body.style_name || 'Custom storyboard').slice(0, 80),
  clips
}}];

const r = $input.first().json;
const id = Array.isArray(r) ? (r[0] && r[0].id) : (r.id ?? (r[0] && r[0].id));
if (!id) throw new Error('Could not read job id from Supabase insert: ' + JSON.stringify(r).slice(0,300));
const plan = $('Plan From Scenes').first().json;
return [{ json: { job_id: id, ...plan } }];

const j = $json;
return j.clips.map(c => ({ json: {
  job_id: j.job_id,
  order: c.order,
  duration: c.duration,
  first_frame_url: c.first_frame_url,
  prompt: c.prompt,
  scene_prompt: c.scene_prompt,
  ratio: j.ratio,
  resolution_used: j.resolution_used
}}));

const items = $input.all();
const srcAll = $('Split Clips').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = srcAll[i].json;
  const binary = items[i].binary || {};
  const key = binary.data ? 'data' : Object.keys(binary)[0];
  if (!key) throw new Error('No reference image fetched for the scene frame');
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  const refB64 = buf.toString('base64');
  const refMime = (binary[key] && binary[key].mimeType) || 'image/jpeg';

  const ratio = src.ratio || '9:16';
  const aspectHint = ratio === '9:16' ? 'Compose it as a tall vertical 9:16 image.'
    : ratio === '1:1' ? 'Compose it as a square 1:1 image.'
    : ratio === '16:9' ? 'Compose it as a wide 16:9 image.' : '';

  const scene = String(src.scene_prompt || src.prompt || '').trim();
  const framePrompt = 'Create ONE photorealistic still image (a single frame) for a premium luxury jewellery reel. The scene: ' + scene
    + ' VERY IMPORTANT - look closely at the attached reference image: if it shows a person or model wearing the jewellery, you MUST keep that SAME model in the new image - the same face, skin tone, hair, makeup and body - still wearing the SAME jewellery, and build this scene around her (do not remove her and do not turn it into a product-only shot). If the reference image is the product on its own with no person, then keep it a product-only shot.'
    + ' In every case the jewellery piece must stay EXACTLY as in the reference image - same design, stones, metal colour, shape and proportions - do not redesign it. Make it look like a high-end advert with beautiful lighting. ' + aspectHint + ' No text, no logos, no watermarks.';

  const geminiImageBody = {
    contents: [{ role: 'user', parts: [ { text: framePrompt }, { inlineData: { mimeType: refMime, data: refB64 } } ] }],
    generationConfig: { responseModalities: ['TEXT','IMAGE'] }
  };

  out.push({ json: {
    job_id: src.job_id, order: src.order, duration: src.duration,
    prompt: src.prompt, ratio: src.ratio, resolution_used: src.resolution_used,
    refB64, refMime, public_id: 'reel-frame_' + src.job_id + '_' + src.order,
    geminiImageBody
  }, binary: items[i].binary, pairedItem: { item: i } });
}
return out;

const items = $input.all();
const srcAll = $('Build Frame Body').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = srcAll[i].json;
  const resp = items[i].json;
  let b64 = null, mime = 'image/png';
  try {
    const cands = resp.candidates || (resp.data && resp.data.candidates) || [];
    for (const c of cands) {
      const parts = (c.content && c.content.parts) || [];
      for (const p of parts) {
        const d = p.inlineData || p.inline_data;
        if (d && d.data) { b64 = d.data; mime = d.mimeType || d.mime_type || 'image/png'; break; }
      }
      if (b64) break;
    }
  } catch (e) {}
  // Fallback: if this scene's frame failed to generate, reuse the original photo.
  if (!b64) { b64 = src.refB64; mime = src.refMime || 'image/jpeg'; }
  const imageData = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), 'frame.png', mime);
  out.push({ json: {
    job_id: src.job_id, order: src.order, duration: src.duration,
    prompt: src.prompt, ratio: src.ratio, resolution_used: src.resolution_used,
    public_id: src.public_id
  }, binary: { imageData }, pairedItem: { item: i } });
}
return out;

const items = $input.all();
const srcAll = $('Decode Frame').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const up = items[i].json;
  const url = up.secure_url || up.url;
  if (!url) throw new Error('Cloudinary returned no URL for the scene frame: ' + JSON.stringify(up).slice(0,200));
  const src = srcAll[i].json;
  out.push({ json: {
    job_id: src.job_id, order: src.order, duration: src.duration,
    first_frame_url: url, prompt: src.prompt,
    ratio: src.ratio, resolution_used: src.resolution_used
  }, pairedItem: { item: i } });
}
return out;

const resp = $json;
const taskId = resp.id || resp.task_id || (resp.data && resp.data.id);
if (!taskId) throw new Error('Seedance create returned no task id: ' + JSON.stringify(resp).slice(0,300));
const src = $('Map Frame').item.json;
return { json: { order: src.order, duration: src.duration, task_id: taskId } };

const items = $input.all();
const tasks = items.map(it => ({
  order: it.json.order, duration: it.json.duration, task_id: it.json.task_id,
  status: 'queued', video_url: null
}));
const meta = $('Attach Job ID').first().json;
const totalSeconds = tasks.reduce((s, t) => s + t.duration, 0);
return [{ json: {
  job_id: meta.job_id, user_id: meta.user_id, music_id: meta.music_id,
  resolution_used: meta.resolution_used,
  overlay_text: meta.overlay_text, overlay_position: meta.overlay_position, overlay_start_at: meta.overlay_start_at,
  attempt: 0, totalSeconds, tasks
}}];

const c = $json;
return c.tasks.map(t => ({ json: {
  job_id: c.job_id, user_id: c.user_id, music_id: c.music_id,
  resolution_used: c.resolution_used, attempt: c.attempt, totalSeconds: c.totalSeconds,
  overlay_text: c.overlay_text, overlay_position: c.overlay_position, overlay_start_at: c.overlay_start_at,
  order: t.order, duration: t.duration, task_id: t.task_id,
  status: t.status, video_url: t.video_url
}}));

const resp = $json;
const src = $('Split Tasks').item.json;
const status = resp.status || (resp.data && resp.data.status) || src.status;
let url = src.video_url;
if (resp.content && resp.content.video_url) url = resp.content.video_url;
else if (resp.data && resp.data.content && resp.data.content.video_url) url = resp.data.content.video_url;
else if (resp.video_url) url = resp.video_url;
return { json: { ...src, status, video_url: url } };

const items = $input.all().map(i => i.json);
const MAX_ATTEMPTS = 20; // 20 x 15s = 5 min ceiling
const attempt = (items[0].attempt || 0) + 1;
const tasks = items.map(t => ({
  order: t.order, duration: t.duration, task_id: t.task_id,
  status: t.status, video_url: t.video_url
})).sort((a, b) => a.order - b.order);

const done = tasks.every(t => String(t.status) === 'succeeded' && t.video_url);
const failed = tasks.some(t => ['failed','cancelled','expired','error'].includes(String(t.status)));
const timedOut = attempt >= MAX_ATTEMPTS;
const m = items[0];
return [{ json: {
  job_id: m.job_id, user_id: m.user_id, music_id: m.music_id,
  resolution_used: m.resolution_used, totalSeconds: m.totalSeconds,
  overlay_text: m.overlay_text, overlay_position: m.overlay_position, overlay_start_at: m.overlay_start_at,
  attempt, tasks,
  allDone: done, anyFailed: failed, timedOut, stop: (failed || timedOut)
}}];

const j = $json;
const clips = j.tasks.filter(t => t.video_url)
  .sort((a, b) => a.order - b.order)
  .map(t => ({ order: t.order, url: t.video_url }));
const totalSeconds = j.totalSeconds;
const costUsd = +(totalSeconds * 0.022).toFixed(4);  // Seedance 1.5 Pro Fast ~ $0.022/s
const costInr = +(costUsd * 94.4).toFixed(2);

// music_url and overlay font/color aren't threaded through the poll loop - read
// them straight from the original plan node.
const plan = $('Plan From Scenes').first().json;
const musicUrl = plan.music_url || null;

const overlay = j.overlay_text ? {
  text: j.overlay_text,
  position: j.overlay_position || 'whole',   // 'whole' | 'end'
  start_at: j.overlay_position === 'end' ? (j.overlay_start_at || 0) : 0,
  font: plan.overlay_font || 'sans',
  color: plan.overlay_color || 'white'
} : null;

return [{ json: {
  job_id: j.job_id, music_id: j.music_id, music_url: musicUrl, clips,
  overlay,
  totalSeconds, cost_usd: costUsd, cost_inr: costInr, clip_urls: clips
}}];

const r = $json; // render response { url, bytes, duration }
const p = $('Build Render Payload').first().json;
return [{ json: {
  job_id: p.job_id,
  patch: {
    status: 'completed',
    output_url: r.url,
    output_bytes: r.bytes || null,
    clip_urls: p.clip_urls,
    cost_usd: p.cost_usd,
    cost_inr: p.cost_inr,
    completed_at: new Date().toISOString()
  }
}}];

let jobId = $json.job_id;
if (!jobId) { try { jobId = $('Build Render Payload').first().json.job_id; } catch (e) {} }
if (!jobId) { try { jobId = $('Aggregate Poll').first().json.job_id; } catch (e) {} }
let msg = 'Reel generation failed';
if ($json.anyFailed) msg = 'One or more Seedance clips failed to generate';
else if ($json.timedOut) msg = 'Generation timed out';
else if ($json.error) msg = 'Render failed: ' + String(typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error)).slice(0, 400);
return [{ json: {
  job_id: jobId,
  patch: { status: 'failed', error_message: msg, completed_at: new Date().toISOString() }
}}];
